const OX_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${OX_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const OX_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OX_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.fo!=null?` fill-opacity="${o.fo}"`:''}${o.ex?' '+o.ex:''}/>`;
const OX_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OX_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OX_GREY='#5C6577';
/* the three wavelengths, coloured as in the notes' figure: λ2 orange, λ3 blue */
const OX_LC={1:'#7048E8',2:'#D9480F',3:'#1C5FD4'};
