 +OX_bar(x[0],80,70,k,[[48,'48 data',BLU]])+OX_bar(x[1],80,70,k,[[42,'42 data',BLU],[6,'',OX_GREY,1]])+OX_bar(x[2],80,70,k,[[40,'pad 40',OX_GREY,1],[8,'8',ORG]])
