 +OX_T(x[1]+42*k+11,232,'pad 6',{fs:22,fw:700,a:'middle',fill:OX_GREY})+OX_T(x[2]+48*k-15,232,'trailer',{fs:22,fw:800,a:'middle',fill:ORG})
