function EXTRA(R,ICON){
 /* hook: a three-leg train trip where seat 12 is taken on the middle leg, and the same puzzle on three fiber links */
 ICON.oxHookTrain=(x,y)=>{let o=`<g transform="translate(${x-190} ${y-80})">${OX_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}`+OX_T(190,36,'seat 12, leg by leg',{fs:24,fw:800,a:'middle',fill:ORG});
  [0,1,2].forEach(i=>{const cx=75+i*115, free=i!==1;o+=OX_T(cx,72,'leg '+(i+1),{fs:22,fw:700,a:'middle',fill:OX_GREY})+`<rect x="${cx-38}" y="86" width="76" height="52" rx="10" fill="${free?GRN:'#FFFFFF'}" fill-opacity="${free?.18:1}" stroke="${free?GRN:MAG}" stroke-width="3"/>`+OX_T(cx,120,free?'free':'taken',{fs:22,fw:800,a:'middle',fill:free?GRN:MAG})});
  return o+'</g>'};
 ICON.oxHookFiber=(x,y)=>{let o=`<g transform="translate(${x-190} ${y-80})">${OX_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}`;
  const xs=[34,138,242,346];o+=OX_L(34,34,346,34,'#ADB5BD',6)+['A','B','C','D'].map((t,i)=>OX_node(xs[i],34,t)).join('');
  OX_FREE.forEach((s,i)=>{s.forEach((n,j)=>{o+=OX_chip((xs[i]+xs[i+1])/2,84+j*46,n)})});
  return o+'</g>'};
 /* recap pictures, about 420 x 330 each */
 ICON.oxRcCont=(x,y)=>{let o=`<g transform="translate(${x-210} ${y-165})">`;const cx=[150,260,370], ry=[70,150,230];
  o+=['A–B','B–C','C–D'].map((t,i)=>OX_T(cx[i],26,t,{fs:24,fw:800,a:'middle'})).join('');
  [1,2,3].forEach((n,j)=>{o+=OX_T(70,ry[j]+9,'λ'+n,{fs:26,fw:800,a:'end',fill:OX_LC[n]});OX_FREE.forEach((s,i)=>{const f=s.includes(n);o+=`<rect x="${cx[i]-48}" y="${ry[j]-30}" width="96" height="60" rx="10" fill="${f?GRN:'#FFFFFF'}" fill-opacity="${f?.2:1}" stroke="${f?GRN:'#ADB5BD'}" stroke-width="3"${f?'':' stroke-dasharray="7 5"'}/>`+(f?'':OX_L(cx[i]-20,ry[j]-14,cx[i]+20,ry[j]+14,MAG,4)+OX_L(cx[i]-20,ry[j]+14,cx[i]+20,ry[j]-14,MAG,4))})});
  return o+OX_T(210,316,'no full row: blocked',{fs:26,fw:800,a:'middle',fill:MAG})+'</g>'};
 ICON.oxRcOxc=(x,y)=>{let o=`<g transform="translate(${x-210} ${y-165})">`;
  for(let i=7;i>=0;i--){const ox=20+i*12, oy=24+i*12;o+=`<rect x="${ox}" y="${oy}" width="110" height="110" fill="#FFF4E6" stroke="${ORG}" stroke-width="2.5"/>`}
  o+=OX_T(95,256,'8 planes, 4 × 4',{fs:24,fw:800,a:'middle',fill:ORG})+OX_T(95,292,'128',{fs:30,fw:800,a:'middle',fill:ORG});
  o+=`<rect x="240" y="40" width="170" height="170" fill="#E7F5FF" stroke="${BLU}" stroke-width="3"/>`;for(let k=1;k<8;k++)o+=OX_L(240+k*21.25,40,240+k*21.25,210,BLU,1)+OX_L(240,40+k*21.25,410,40+k*21.25,BLU,1);
  return o+OX_T(325,256,'one 32 × 32',{fs:24,fw:800,a:'middle',fill:BLU})+OX_T(325,292,'1024',{fs:30,fw:800,a:'middle',fill:BLU})+'</g>'};
 ICON.oxRcCell=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${OX_T(210,40,'one cell, 53 B',{fs:26,fw:800,a:'middle',fill:GRN})}${OX_bar(10,64,80,7.5,[[5,'5',GRN],[48,'48 B',BLU]],26)}
${OX_T(210,206,'the last cell',{fs:26,fw:800,a:'middle',fill:ORG})}${OX_bar(10,228,80,7.5,[[5,'5',GRN],[12,'12',BLU],[28,'pad',OX_GREY,1],[8,'8',ORG]],26)}</g>`;
}
